def apply_suffix_before_extension(names, suffix):
    result = []
    for name in names:
        i = name.rfind(".")
        if i > 0:
            base = name[:i]
            ext = name[i:]
            result.append(base + suffix + ext)
        else:
            result.append(name + suffix)
    print("Archived", len(names), "items")
    return result
